svg.script:
(function() {
  'use strict';

  // Status text sequences for each component
  const statusSequences = {
    auth: ['AUTHENTICATING', 'VALIDATING KEY', 'AUTHENTICATED ✓'],
    route: ['ROUTING', 'RESOLVING ENDPOINT', 'FORWARDING'],
    controller: ['PROCESSING', 'PREPARING CONTEXT', 'INVOKING SANDBOX'],
    docker: ['CONTAINER STARTING', 'MOUNTING VOLUMES', 'RUNNING'],
    exec: ['QUEUED', 'COMPILING', 'RUNNING', 'CAPTURING OUTPUT', 'COMPLETED'],
    metrics: ['COLLECTING', 'READING CGROUPS', 'CALCULATING', 'READY'],
    cleanup: ['CLEANING', 'REMOVING CONTAINER', 'DELETING TEMP', 'CLEAN ✓']
  };

  const statusElements = {
    auth: document.getElementById('authStatusText'),
    route: document.getElementById('statusRoute').querySelector('text'),
    controller: document.getElementById('statusController').querySelector('text'),
    docker: document.getElementById('dockerStatusText'),
    exec: document.getElementById('execStatusText'),
    metrics: document.getElementById('statusMetrics').querySelector('text'),
    cleanup: document.getElementById('cleanupStatusText')
  };

  let cycleIndex = 0;
  const sequenceLength = Math.max(...Object.values(statusSequences).map(s => s.length));

  function updateStatuses() {
    cycleIndex = (cycleIndex + 1) % sequenceLength;
    Object.entries(statusSequences).forEach(([key, seq]) => {
      const el = statusElements[key];
      if (el && seq[cycleIndex % seq.length]) {
        el.textContent = seq[cycleIndex % seq.length];
      }
    });
  }

  // Update every 3 seconds
  setInterval(updateStatuses, 3000);

  // Initial setup
  document.addEventListener('DOMContentLoaded', function() {
    // Force animations to start
    document.querySelectorAll('.component-card').forEach(function(card) {
      card.style.animationPlayState = 'running';
    });
  });

  // Intersection observer for performance (pause when not visible)
  if (typeof IntersectionObserver !== 'undefined') {
    const observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        document.querySelectorAll('animate, animateMotion, animateTransform').forEach(function(anim) {
          if (entry.isIntersecting) {
            anim.beginElement();
          }
        });
      });
    }, { threshold: 0.1 });
    observer.observe(document.documentElement);
  }
})();
